import{_ as e,a as i,b as o}from"./chunks/m_filtrace.DRtLeEEZ.js";import{_ as n}from"./chunks/m_btn_hamburger.CftTsS04.js";import{_ as a,a as s}from"./chunks/m_btn_newtask.BnGNwNK5.js";import{_ as r,o as c,c as l,aa as d}from"./chunks/framework.BAs_AphD.js";const g="/buildary-help-preview/media/cs/tickets/m_btn_dodeniku.png",h="/buildary-help-preview/media/cs/tickets/m_ikona_vyjadreni.png",S=JSON.parse('{"title":"Ticket List","description":"","frontmatter":{"title":"Ticket List","wiki":"en:tickets:m_task_grid"},"headers":[],"relativePath":"en/tickets/m_task_grid.md","filePath":"en/tickets/m_task_grid.md","lastUpdated":1794388980000}'),m={name:"en/tickets/m_task_grid.md"};function p(f,t,k,_,u,w){return c(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="ticket-list" tabindex="-1">Ticket List <a class="header-anchor" href="#ticket-list" aria-label="Permalink to &quot;Ticket List&quot;">​</a></h1><figure class="shot" style="--w:280px;"><img src="'+e+'" alt="Ticket List for the Project" width="250" loading="lazy"></figure><figure class="shot" style="--w:280px;"><img src="'+i+'" alt="Ticket Details in the List" width="250" loading="lazy"></figure><p><strong>In the blue header</strong> of the Ticket List, there is a <strong>hamburger menu <img src="'+n+'" alt="Hamburger Menu" width="25" data-no-zoom loading="lazy"> on the left for opening the navigation menu</strong>, and the <strong><img src="'+g+'" alt="Switch to Project Diary" width="25" data-no-zoom loading="lazy"> icon on the right for quickly switching to the project&#39;s Project Diary</strong>.</p><p><strong>Below the header is the filter row</strong>, followed by the list of tickets.</p><p><strong>Each ticket card contains:</strong></p><ul><li>in the card header: <strong>Ticket Number</strong> / <strong>Ticket Status</strong> / <strong>Priority</strong>. The <img src="'+h+'" alt="Statement Icon" width="20" data-no-zoom loading="lazy"> icon on the right indicates the presence of a <strong>Statement</strong> for the ticket. It is displayed only for tickets that contain a Statement.</li><li>in the main field: <strong>Ticket Subject</strong> ⇒ this field is active and opens the ticket for editing</li><li>at the bottom of the card: Information about the <strong>number of attachments</strong> / <strong>Details</strong> ⇒ this icon is active and expands/collapses the basic ticket information (see the image on the right)</li></ul><p>At the bottom right of the page are the <img src="'+a+'" alt="New Photo for Creating a Ticket" width="30" data-no-zoom loading="lazy"> and <img src="'+s+'" alt="New Ticket" width="30" data-no-zoom loading="lazy"> icons ⇒ these icons are used to create a new ticket.</p><h2 id="ticket-filtering" tabindex="-1">Ticket Filtering <a class="header-anchor" href="#ticket-filtering" aria-label="Permalink to &quot;Ticket Filtering&quot;">​</a></h2><figure class="shot" style="--w:280px;"><img src="'+o+'" alt="Ticket Filtering" width="250" loading="lazy"></figure><p>The entire row labeled <strong>Filtering</strong> is active and opens the filter window. The filter window then offers many options for creating a filter.</p><p>Filters can, of course, be combined.</p><ul><li><strong>Search field with magnifying glass</strong> → allows you to find tickets <strong>containing the entered keyword in the subject or description</strong>. The application supports word declension, so it is sufficient to enter the word in its basic form.</li><li><strong>Calendar</strong> icon → opens a calendar window where you can enter <strong>up to 4 dates</strong> for the planned / actual start / end of the ticket.</li><li><strong>Relationship to Ticket</strong> → opens a list of ticket statuses, from which 1 can be selected.</li><li><strong>Ticket Status and Deadline</strong> → opens a list of options, from which 1 can be selected.</li><li>a list of additional parameters that can be <strong>filtered using multiselect</strong>, meaning that multiple options can be selected for each parameter → by clicking the row name or the filter (funnel) icon, or <strong>sorted</strong> using the icon at the end of the row: ascending (1st click) - descending (2nd click) - disable sorting (3rd click)</li></ul>',13)])])}const P=r(m,[["render",p]]);export{S as __pageData,P as default};
